void MailScreen::GameButtonDown(Sexy::GamepadButton theButton, int thePlayerIndex, unsigned int theFlags)
{
  (void)thePlayerIndex;
  int aMessageCount = (int)(mPage == 1 ? mReadList.size() : mUnreadList.size());

  if (theButton == GAMEPAD_BUTTON_RIGHT && (theFlags & 1u) == 0)
  {
    int aIndex = ++mCurrentListPos;
    if (aMessageCount > 0)
    {
      if (aMessageCount > aIndex)
      {
        SetCurrentMessageIndex(aIndex);
        MessagesShiftLeft();
      }
      else
      {
        mCurrentListPos = aMessageCount - 1;
      }
    }
    mRightHintAnimTime = 0.0f;
    mRightHintAnimValue = 4.0f;
  }
  else if (theButton == GAMEPAD_BUTTON_LEFT && (theFlags & 1u) == 0)
  {
    int aIndex = --mCurrentListPos;
    if (aMessageCount > 0)
    {
      if (aIndex >= 0)
      {
        SetCurrentMessageIndex(aIndex);
        MessagesShiftRight();
      }
      else
      {
        mCurrentListPos = 0;
      }
    }
    mLeftHintAnimTime = 0.0f;
    mLeftHintAnimValue = 4.0f;
  }
  else if (theButton == GAMEPAD_BUTTON_A)
  {
    if (mPage == 0 && aMessageCount > 0)
    {
      mApp->mMailBox->MarkMessageRead(mCurrentMessageIndex);
      InitMessages();
      mCurrentListPos = 0;
      SetCurrentMessageIndex(0);
    }
    return;
  }
  else if (theButton == GAMEPAD_BUTTON_Y)
  {
    mApp->mMailBox->GetMessageByIndex(mCurrentMessageIndex, true);
    return;
  }
  else if (theButton == GAMEPAD_BUTTON_X)
  {
    mPage = (mPage != 1);
    InitMessages();
    mCurrentListPos = 0;
    SetCurrentMessageIndex(0);
    if ( mPage != 0 )
    {
      mApp->mHelpBarWidget->ClearButtons(0);
      mApp->mHelpBarWidget->AddButton(GAMEPAD_BUTTON_A, "[SWITCH_MESSAGE]", HELP_ALIGN_RIGHT);
      mApp->mHelpBarWidget->AddButton(GAMEPAD_BUTTON_B, "[GO_TO_INBOX]", HELP_ALIGN_LEFT);
      mApp->mHelpBarWidget->AddButton(GAMEPAD_BUTTON_Y, "[BACK]", HELP_ALIGN_LEFT);
    }
    else
    {
      mApp->mHelpBarWidget->ClearButtons(0);
      mApp->mHelpBarWidget->AddButton(GAMEPAD_BUTTON_A, "[SWITCH_MESSAGE]", HELP_ALIGN_RIGHT);
      mApp->mHelpBarWidget->AddButton(GAMEPAD_BUTTON_X, "[MARK_MESSAGE_READ]", HELP_ALIGN_RIGHT);
      mApp->mHelpBarWidget->AddButton(GAMEPAD_BUTTON_B, "[GO_TO_READ_MAIL]", HELP_ALIGN_LEFT);
      mApp->mHelpBarWidget->AddButton(GAMEPAD_BUTTON_Y, "[BACK]", HELP_ALIGN_LEFT);
    }
  }
  else if (theButton == GAMEPAD_BUTTON_B || theButton == 4)
  {
    mApp->TryToSaveProfile();
    mButtonDelay = 1000;
  }
}

